import asyncio
import logging
from typing import List, Type, Dict, Any
from .plugins.base import ScannerPlugin, Finding

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(name)s: %(message)s'
)
logger = logging.getLogger("SwarmOS.VulnScanner")

class ScanEngine:
    """
    High-performance asynchronous engine for executing vulnerability scans.
    """
    def __init__(self, concurrency_limit: int = 100):
        self.plugins: List[ScannerPlugin] = []
        self.semaphore = asyncio.Semaphore(concurrency_limit)
        self.results: List[Finding] = []

    def register_plugin(self, plugin_cls: Type[ScannerPlugin], config: Dict[str, Any]):
        """Instantiates and registers a plugin into the engine."""
        plugin_instance = plugin_cls(config)
        self.plugins.append(plugin_instance)
        logger.info(f"Registered plugin: {plugin_instance.plugin_id}")

    async def _execute_plugin(self, plugin: ScannerPlugin, target: str):
        """Wraps plugin execution with concurrency control and error handling."""
        async with self.semaphore:
            try:
                logger.debug(f"Executing {plugin.plugin_id} on {target}...")
                findings = await plugin.run(target)
                self.results.extend(findings)
            except Exception as e:
                logger.error(f"Plugin {plugin.plugin_id} failed on {target}: {str(e)}")

    async def scan(self, target: str):
        """
        Orchestrates the execution of all registered plugins against a target.
        """
        logger.info(f"Initiating vulnerability scan for target: {target}")
        tasks = [self._execute_plugin(plugin, target) for plugin in self.plugins]
        await asyncio.gather(*tasks)
        logger.info(f"Scan complete. Total findings: {len(self.results)}")
        return self.results